/* Original sky/water effects through real GPU rendering into an arbitrary FBO. */
#include "render.hpp"
#include "gpu.hpp"
#include "original.hpp"
#include <SDL.h>
#include <nlohmann/json.hpp>
#include <iostream>
int main(int argc,char**argv){try{
 if(argc!=3)throw std::runtime_error("assets original-fixtures");SDL_Init(SDL_INIT_VIDEO);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,3);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,3);SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_CORE);
 auto*window=SDL_CreateWindow("Original sky and water GPU check",0,0,640,480,SDL_WINDOW_OPENGL|SDL_WINDOW_HIDDEN);if(!window)throw std::runtime_error(SDL_GetError());auto context=SDL_GL_CreateContext(window);glewExperimental=GL_TRUE;auto result=glewInit();if(result!=GLEW_OK&&!GLEW_VERSION_3_3)throw std::runtime_error("GL3.3 unavailable");while(glGetError()){}
 unsigned fbo,color,depth;glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glGenTextures(1,&color);glBindTexture(GL_TEXTURE_2D,color);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,640,480,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,color,0);glGenRenderbuffers(1,&depth);glBindRenderbuffer(GL_RENDERBUFFER,depth);glRenderbufferStorage(GL_RENDERBUFFER,GL_DEPTH_COMPONENT24,640,480);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depth);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw std::runtime_error("Test FBO incomplete");glViewport(0,0,640,480);
 {ab3d2::Renderer renderer;renderer.loadAssets(argv[1]);std::ifstream memory(std::filesystem::path(argv[2])/"level-9.ram",std::ios::binary);memory.read(reinterpret_cast<char*>(Mem::RAM.data()),Mem::RAM_SIZE);Mem::cursor=memory.gcount();renderer.loadLevel(9);renderer.sync();
 float f=1/std::tan(80*3.14159265f/360),near=.03f,far=300;ab3d2::Matrix projection{f/(4.f/3),0,0,0,0,f,0,0,0,0,(far+near)/(near-far),-1,0,0,2*far*near/(near-far),0};
 auto pose=[&](float x,float y,float z,float yaw,float pitch){float c=std::cos(pitch),s=std::sin(pitch);ab3d2::Matrix rx{1,0,0,0,0,c,s,0,0,-s,c,0,0,0,0,1},inverseRX{1,0,0,0,0,c,-s,0,0,s,c,0,0,0,0,1};ab3d2::RenderView view;view.headWorld=ab3d2::gpu::multiply(ab3d2::gpu::transform(x,y,z,yaw),rx);view.camera={x,y,z};auto inverse=ab3d2::gpu::multiply(inverseRX,ab3d2::gpu::multiply(ab3d2::gpu::transform(0,0,0,-yaw),ab3d2::gpu::transform(-x,-y,-z)));view.viewProjection=ab3d2::gpu::multiply(projection,inverse);return view;};
 auto capture=[&](const ab3d2::RenderView&view){glClearColor(0,0,0,1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);int beforeRead,beforeDraw;glGetIntegerv(GL_READ_FRAMEBUFFER_BINDING,&beforeRead);glGetIntegerv(GL_DRAW_FRAMEBUFFER_BINDING,&beforeDraw);renderer.drawEye(view);int afterRead,afterDraw;glGetIntegerv(GL_READ_FRAMEBUFFER_BINDING,&afterRead);glGetIntegerv(GL_DRAW_FRAMEBUFFER_BINDING,&afterDraw);if(beforeRead!=afterRead||beforeDraw!=afterDraw)throw std::runtime_error("GPU water changed caller framebuffer bindings");auto error=glGetError();if(error)throw std::runtime_error("Effect GL error "+std::to_string(error));std::vector<unsigned char> px(640*480*3);glPixelStorei(GL_PACK_ALIGNMENT,1);glReadPixels(0,0,640,480,GL_RGB,GL_UNSIGNED_BYTE,px.data());return px;};
 auto sky0=capture(pose(0,1000,0,0,0)),skyHalf=capture(pose(0,1000,0,3.14159265f,0)),skyQuarter=capture(pose(0,1000,0,1.57079633f,0));double halfError=0,quarterError=0;for(size_t n=0;n<sky0.size();++n){halfError+=std::abs(int(sky0[n])-int(skyHalf[n]));quarterError+=std::abs(int(sky0[n])-int(skyQuarter[n]));}halfError/=sky0.size();quarterError/=sky0.size();if(halfError>1||quarterError<3)throw std::runtime_error("Original sky half-turn repeat failed: "+std::to_string(halfError)+"/"+std::to_string(quarterError));
 nlohmann::json data;std::ifstream(std::filesystem::path(argv[1])/"levels/j.json")>>data;auto surface=*std::find_if(data["flats"].begin(),data["flats"].end(),[](const auto&v){return v["kind"]=="water";});int zone=surface["zone"];auto edges=data["zones"][zone]["edges"];float x=0,z=0;for(const auto&e:edges){x+=e["x"].get<float>()/64;z-=e["z"].get<float>()/64;}x/=edges.size();z/=edges.size();float water=-surface["y"].get<float>()/128;
 Mem::ww(PlayerBss::Plr1_Zone_w,zone);Mem::wl(HiresData::draw_WaterFramePtr_l,Mem::l(HiresData::draw_WaterFramePtrs_vl));renderer.sync();auto phase0=capture(pose(x,water+1.5f,z,0,-1.0f));Mem::wl(HiresData::draw_WaterFramePtr_l,Mem::l(HiresData::draw_WaterFramePtrs_vl+4*4));Mem::ww(HiresData::wtan,Mem::uw(HiresData::wtan)+640);renderer.sync();auto phase4=capture(pose(x,water+1.5f,z,0,-1.0f));if(phase0==phase4)throw std::runtime_error("Original water phases produced identical GPU images");auto submerged=capture(pose(x,water-.4f,z,0,0));if(submerged==phase4)throw std::runtime_error("Underwater palette did not change the view");
 std::cout<<"PASS original sky two-repeats/turn (half error "<<halfError<<", quarter "<<quarterError<<"), water wave/refraction phases, underwater palette, arbitrary FBO preservation\n";
 }
 glBindFramebuffer(GL_FRAMEBUFFER,0);glDeleteRenderbuffers(1,&depth);glDeleteTextures(1,&color);glDeleteFramebuffers(1,&fbo);SDL_GL_DeleteContext(context);SDL_DestroyWindow(window);SDL_Quit();
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
